        const extendsRun = run && comment.loc.start.line === run.endLine + 1;
        if (extendsRun) {
            run.comments.push(comment);
            run.endLine = comment.loc.end.line;
            continue;
        }
        run = {
            comments: [comment],
            endLine: comment.loc.end.line,
        };
        runs.push(run);
    }
    return runs;
}
/** Every comment span in the file as `{ node, count }` — one entry per block
 * comment, one per run of consecutive line comments (reported at its first line). */
function commentSpans(comments) {
    const blocks = comments
        .filter((comment) => comment.type === "Block")
        .map((block) => ({
        node: block,
        count: block.loc.end.line - block.loc.start.line + 1,
    }));
    const runs = groupLineRuns(comments.filter((comment) => comment.type === "Line")).map((run) => ({ node: run.comments[0], count: run.comments.length }));
    return [...blocks, ...runs];
}
export default {
    meta: {
        type: "suggestion",
        docs: {
            description: "Limit how many lines a comment (or run of consecutive line comments) may span; 0 bans comments entirely",
        },
        schema: [
            {
                type: "object",
                properties: { max: { type: "integer", minimum: 0 } },
                additionalProperties: false,
            },
        ],
        messages: {
            tooLong: "Comment spans {{count}} lines (max {{max}}) — state the one constraint the code cannot show, or move the essay to a spec/ADR.",
            noComments: "No comments in test files — the test name and the code must carry the meaning.",
        },
    },
    create(context) {
        const max = context.options[0]?.max ?? 1;
        function report({ node, count }) {
            if (max === 0) {
                context.report({ node, messageId: "noComments" });
                return;
            }
            context.report({
                node,
                messageId: "tooLong",
                data: { count, max },
            });
        }
        return {
            Program() {
                const comments = context.sourceCode
                    .getAllComments()
                    .filter((comment) => !isDirective(comment));
                commentSpans(comments)
                    .filter((span) => span.count > max)
                    .forEach(report);
            },
        };
    },
};

