    expect({
      replyType: replyDuringTurn.type,
      listedIds: listedConversations.map(row => row.sessionId),
      answeredBeforeStreamEnd: !streamEndedEarly,
      recordedCalls,
    }).toEqual({
      replyType: 'conversation_list',
      listedIds: ['s-own', freshId],
      answeredBeforeStreamEnd: true,
      recordedCalls: [{userId: 'u1', limit: undefined, before: undefined}],
    });
  });

  it('validates list_conversations and refuses malformed limit or before cursors', () => {
    const cursor = {updatedAt: '2099-06-01T12:00:00.000Z', sessionId: 's1'};
    const invalidLimits = [0, 201, 1.5, '10'];
    const invalidCursors = [
      'not a date',
      {updatedAt: '2099-06-01T12:00:00.000Z'},
      {sessionId: 's1'},
      {updatedAt: 'not a date', sessionId: 's1'},
      {updatedAt: '2099-06-01T12:00:00.000Z', sessionId: ''},
    ];

    expect({
      bare: validateMessage({type: 'list_conversations', userId: 'u2'}),
      paged: validateMessage({type: 'list_conversations', limit: 200, before: cursor, userId: 'u2'}),
      rejectedLimits: invalidLimits.map(limit =>
        namedFailure(validateMessage({type: 'list_conversations', limit}), 'limit')
      ),
      rejectedCursors: invalidCursors.map(before =>
        namedFailure(validateMessage({type: 'list_conversations', before}), 'before')
      ),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_conversations'}},
      paged: {valid: true, data: {type: 'list_conversations', limit: 200, before: cursor}},
      rejectedLimits: ['invalid:limit', 'invalid:limit', 'invalid:limit', 'invalid:limit'],
      rejectedCursors: ['invalid:before', 'invalid:before', 'invalid:before', 'invalid:before', 'invalid:before'],
    });
  });

  it('answers UNSUPPORTED when unavailable and SERVER_ERROR without store detail on failure', async () => {
    const defaultOffFrames = await querySingleEngine({
      store: new InMemorySessionStore(),
      resume: {enabled: true},
    });
    const fiveMemberFrames = await querySingleEngine({
      store: storeLackingListFor(new InMemorySessionStore()),
      resume: {enabled: true},
      history: {enabled: true},
    });
    const lackingFindFrames = await querySingleEngine({
      store: createMongoSessionStore({collection: collectionLackingFind()}),
      resume: {enabled: true},
      history: {enabled: true},
    });
    const failureOutcome = await runRejectingStoreScenario();

    expect({
      defaultOff: defaultOffFrames.map(frame => ({type: frame.type, code: frame.code})),
      fiveMember: fiveMemberFrames.map(frame => ({type: frame.type, code: frame.code})),
      collectionWithoutFind: lackingFindFrames.map(frame => ({type: frame.type, code: frame.code})),
      rejectedList: failureOutcome.frames.map(frame => ({type: frame.type, code: frame.code})),
      warnedWithoutResume: failureOutcome.warnedWithoutResume,
      loggedSessionId: failureOutcome.loggedSessionId,
      leakedStoreHost: failureOutcome.leakedStoreHost,
      leakedUserContent: failureOutcome.leakedUserContent,
    }).toEqual({
      defaultOff: [{type: 'error', code: 'UNSUPPORTED'}],
      fiveMember: [{type: 'error', code: 'UNSUPPORTED'}],
      collectionWithoutFind: [{type: 'error', code: 'UNSUPPORTED'}],
      rejectedList: [{type: 'error', code: 'SERVER_ERROR'}],
      warnedWithoutResume: true,
      loggedSessionId: true,
      leakedStoreHost: false,
      leakedUserContent: false,
    });
  });
