async function listDuringOpenTurn(
  socket: WebSocket,
  turnStarted: {until: Promise<void>},
  releaseTurn: {open: () => void}
): Promise<{replyDuringTurn: WireFrame; streamEndedEarly: boolean}> {
  const turnTrace = traceTurnAndList(socket);
  socket.send(JSON.stringify({type: 'user_message', content: 'hold this turn open'}));
  await turnStarted.until;
  socket.send(JSON.stringify({type: 'list_conversations', userId: 'u2'}));
  const replyDuringTurn = await turnTrace.listReply;
  const streamEndedEarly = turnTrace.seenTypes.includes('stream_end');
  releaseTurn.open();
  await turnTrace.turnEnded;
  return {replyDuringTurn, streamEndedEarly};
}

async function runRejectingStoreScenario(): Promise<{
  frames: WireFrame[];
  warnedWithoutResume: boolean;
  loggedSessionId: boolean;
  leakedStoreHost: boolean;
  leakedUserContent: boolean;
}> {
  const warnings: string[] = [];
  const loggedErrors: Array<{message: string; meta?: Record<string, unknown>}> = [];
  installLogSink(warnings, loggedErrors);
  const brokenUrl = await startHistoryEngine({
    store: rejectingListStore(new InMemorySessionStore(), 'db-node-01.internal:27017 ECONNRESET'),
    history: {enabled: true},
  });
  const {socket, initialFrames} = await connectClient(brokenUrl);
  await completeTurn(socket, 'confidential-symptom-note');
  const frames = await askList(socket, {type: 'list_conversations'}, 99);
  const failingSessionId = initialFrames[0]?.sessionId ?? '';
  const errorMessage = frames[0]?.message ?? '';
  const serializedErrors = JSON.stringify(loggedErrors);
  return {
    frames,
    warnedWithoutResume: warnings.length > 0,
    loggedSessionId: loggedErrors.some(entry => entry.meta?.sessionId === failingSessionId),
    leakedStoreHost: errorMessage.includes('db-node-01.internal'),
    leakedUserContent: serializedErrors.includes('confidential-symptom-note'),
  };
}

