async function startHistoryEngine(options: EngineRunOptions): Promise<string> {
  const transport = {
    port: 0,
    resume: options.resume,
    history: options.history,
  };
  const engine = createHalEngine({
    provider: {type: 'mock'},
    prompt: {identity: 'History acceptance assistant.'},
    auth: {ws: async () => ({id: 'u1'})},
    session: options.store,
    orchestrator: options.hooks ? {hooks: options.hooks} : undefined,
    transport,
  });
  await engine.start(0);
  runningEngines.push(engine);
  const address = engine.server.address() as AddressInfo;
  return `ws://127.0.0.1:${address.port}/hal/ws`;
}

async function connectClient(url: string): Promise<{socket: WebSocket; initialFrames: WireFrame[]}> {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 'valid-token']);
  openSockets.push(socket);
  const initialFrames: WireFrame[] = [];
  const settled = new Promise<void>((resolve, reject) => {
    const onMessage = (raw: Buffer) => {
      const frame = JSON.parse(raw.toString()) as WireFrame;
      if (frame.type === 'pong' && frame.timestamp === 0) {
        socket.off('message', onMessage);
        resolve();
        return;
      }
      initialFrames.push(frame);
      if (frame.type === 'connected') {
        socket.send(JSON.stringify({type: 'ping', timestamp: 0}));
      }
    };
    socket.on('message', onMessage);
    socket.once('error', reject);
  });
  await once(socket, 'open');
  await settled;
  return {socket, initialFrames};
}

function askList(socket: WebSocket, payload: Record<string, unknown>, barrierTimestamp: number): Promise<WireFrame[]> {
  const frames: WireFrame[] = [];
  return new Promise<WireFrame[]>((resolve, reject) => {
    let pingSent = false;
    const onMessage = (raw: Buffer) => {
      const frame = JSON.parse(raw.toString()) as WireFrame;
      if (frame.type === 'pong' && frame.timestamp === barrierTimestamp) {
        socket.off('message', onMessage);
        resolve(frames);
        return;
      }
      frames.push(frame);
      if (!pingSent && (frame.type === 'conversation_list' || frame.type === 'error')) {
        pingSent = true;
        socket.send(JSON.stringify({type: 'ping', timestamp: barrierTimestamp}));
      }
    };
    socket.on('message', onMessage);
    socket.once('error', reject);
    socket.send(JSON.stringify(payload));
  });
}

function completeTurn(socket: WebSocket, content: string): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const onMessage = (raw: Buffer) => {
      const frame = JSON.parse(raw.toString()) as WireFrame;
      if (frame.type === 'stream_end') {
        socket.off('message', onMessage);
        resolve();
      }
    };
    socket.on('message', onMessage);
    socket.once('error', reject);
    socket.send(JSON.stringify({type: 'user_message', content}));
  });
}

function traceTurnAndList(socket: WebSocket): {
  seenTypes: string[];
  listReply: Promise<WireFrame>;
  turnEnded: Promise<void>;
} {
  const seenTypes: string[] = [];
  let resolveReply = (_frame: WireFrame): void => undefined;
  let resolveEnd = (): void => undefined;
  const listReply = new Promise<WireFrame>(resolve => {
    resolveReply = resolve;
  });
  const turnEnded = new Promise<void>(resolve => {
    resolveEnd = resolve;
  });
  const onMessage = (raw: Buffer) => {
    const frame = JSON.parse(raw.toString()) as WireFrame;
    seenTypes.push(frame.type);
    if (frame.type === 'conversation_list' || frame.type === 'error') {
      resolveReply(frame);
    }
    if (frame.type === 'stream_end') {
      socket.off('message', onMessage);
      resolveEnd();
    }
  };
  socket.on('message', onMessage);
  return {seenTypes, listReply, turnEnded};
}

function deferredGate(): {until: Promise<void>; open: () => void} {
  let open = (): void => undefined;
  const until = new Promise<void>(resolve => {
    open = resolve;
  });
  return {until, open};
}

function namedFailure(result: ValidationResult, expectedField: string): string {
  if (result.valid) return 'accepted';
  const lowered = result.error.toLowerCase();
  return lowered.includes(expectedField) ? `invalid:${expectedField}` : result.error;
}

function recordingListStore(inner: InMemorySessionStore, calls: RecordedListCall[]): SessionStore {
  return {
    create: (id, userId, options) => inner.create(id, userId, options),
    get: id => inner.get(id),
    delete: id => inner.delete(id),
    count: () => inner.count(),
    clear: () => inner.clear(),
    listFor: (userId, options) => {
      calls.push({userId, limit: options?.limit, before: options?.before});
      return inner.listFor(userId, options);
    },
  };
}

function storeLackingListFor(inner: InMemorySessionStore): SessionStore {
  return {
    create: (id, userId, options) => inner.create(id, userId, options),
    get: id => inner.get(id),
    delete: id => inner.delete(id),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}

function rejectingListStore(inner: InMemorySessionStore, reason: string): SessionStore {
  return {
    create: (id, userId, options) => inner.create(id, userId, options),
    get: id => inner.get(id),
    delete: id => inner.delete(id),
    count: () => inner.count(),
    clear: () => inner.clear(),
    listFor: async () => {
      throw new Error(reason);
    },
  };
}

function collectionLackingFind(): CollectionLike<MongoSessionDocument> {
  return {
    findOne: async () => null,
    updateOne: async () => undefined,
    deleteOne: async () => ({deletedCount: 0}),
    deleteMany: async () => ({deletedCount: 0}),
    countDocuments: async () => 0,
  };
}

function installLogSink(
  warnings: string[],
  errors: Array<{message: string; meta?: Record<string, unknown>}>
): void {
  const ignore = (): void => undefined;
  setLogger({
    debug: ignore,
    info: ignore,
    warn: (_category, message) => {
      warnings.push(message);
    },
    error: (_category, message, meta) => {
      errors.push({message, meta});
    },
  });
}

